sys_script_include.script:
var GetVendingMachineInfo = Class.create();
GetVendingMachineInfo.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getInfo: function() {
        var vmID = this.getParameter('sysparm_vm_id');
        var vm = new GlideRecord('x_1650712_4dot_m_0_vending_machine_service'); // table name
        if (vm.get(vmID)) {
            return 'Last serviced on: ' + vm.getDisplayValue('last_time_serviced') +
                   ', Current state: ' + vm.getDisplayValue('state');
        }
        return 'Info not available';
    }
});
